  k.P(hG, `M0 ${-h * 0.16} Q${-h * 0.05} ${-h * 0.27} ${-h * 0.11} ${-h * 0.24} Q${-h * 0.03} ${-h * 0.18} ${h * 0.04} ${-h * 0.14}Z`, "#7a7067");
