  // Button split seam and raised scroll wheel on the front slope (+x side)
  k.R(g, w * 0.1, topY * 0.52, w * 0.28, mh * 0.035, k.dark(color, 0.32), mh * 0.015);
  k.R(g, w * 0.2, topY * 0.68, w * 0.13, mh * 0.14, color2, mh * 0.04);
